begin;
create table public.social_blocks(blocker_id uuid not null default auth.uid() references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
alter table public.social_blocks enable row level security;
create policy block_owner on public.social_blocks for all to authenticated using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());
grant select,insert(blocked_id),delete on public.social_blocks to authenticated;
create function public.social_blocked(other uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.social_blocks where (blocker_id=auth.uid() and blocked_id=other) or (blocked_id=auth.uid() and blocker_id=other))$$;
revoke all on function public.social_blocked(uuid) from public;
grant execute on function public.social_blocked(uuid) to anon,authenticated;
create policy posts_block_guard on public.social_posts as restrictive for select using(not public.social_blocked(user_id));
create policy follows_block_guard on public.social_follows as restrictive for all using(not public.social_blocked(follower_id) and not public.social_blocked(following_id)) with check(not public.social_blocked(follower_id) and not public.social_blocked(following_id));
create policy comments_block_guard on public.social_comments as restrictive for select using(not public.social_blocked(user_id));
create policy comments_insert_block_guard on public.social_comments as restrictive for insert with check(exists(select 1 from public.social_posts p where p.id=post_id) and (parent_id is null or exists(select 1 from public.social_comments c where c.id=parent_id)));
create policy likes_insert_block_guard on public.social_likes as restrictive for insert with check(exists(select 1 from public.social_posts p where p.id=post_id));
create policy notices_block_guard on public.social_notifications as restrictive for select using(not public.social_blocked(actor_id));
create table public.social_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null default auth.uid() references auth.users(id) on delete cascade,post_id uuid references public.social_posts(id) on delete set null,comment_id uuid references public.social_comments(id) on delete set null,reason text not null check(reason in ('spam','harassment','hate','sexual','violence','other')),details text not null default '' check(char_length(details)<=1000),status text not null default 'pending' check(status in ('pending','resolved','dismissed')),created_at timestamptz not null default now());
alter table public.social_reports enable row level security;
create policy report_submit on public.social_reports for insert to authenticated with check(reporter_id=auth.uid() and status='pending' and ((post_id is not null and comment_id is null and exists(select 1 from public.social_posts p where p.id=post_id)) or (comment_id is not null and post_id is null and exists(select 1 from public.social_comments c where c.id=comment_id))));
create policy report_read on public.social_reports for select to authenticated using(reporter_id=auth.uid() or public.has_staff_role(array['admin','moderator']));
create policy report_staff_update on public.social_reports for update to authenticated using(public.has_staff_role(array['admin','moderator'])) with check(public.has_staff_role(array['admin','moderator']));
revoke all on public.social_reports from anon,authenticated;
grant select,insert(post_id,comment_id,reason,details),update(status) on public.social_reports to authenticated;
create index social_reports_queue_idx on public.social_reports(status,created_at);
notify pgrst,'reload schema';
commit;
